/** One footprint and entrance model shared by street rendering, room previews and travel. */
const DIRS=[[0,-1],[1,0],[0,1],[-1,0]],VECTORS={north:[0,-1],east:[1,0],south:[0,1],west:[-1,0]};
export function doorVector(side){return Array.isArray(side)?side:VECTORS[side]||[0,1];}
export function rotateCell([x,y],turns){for(let i=0;i<turns;i++)[x,y]=[-y,x];return[x,y];}
export function resolveBuildingTarget(data,from,exit){if(exit.to_region){const m=data.campaign.missions[exit.to_region-1];return (exit.to_room?m?.rooms.find(s=>s.key===exit.to_room):exit.to==='hub'?m?.rooms[0]:m?.rooms.find(s=>s.key===exit.to))||null;}if(exit.to==='hub')return null;return data.scenes.find(s=>s.chapter===from.chapter&&s.key===exit.to)||data.scenes.find(s=>s.key===exit.to)||null;}
function reachable(s){const q=[s.arrive],seen=new Set([s.arrive.join(',')]);for(let i=0;i<q.length;i++)for(const[dx,dy]of DIRS){const x=q[i][0]+dx,y=q[i][1]+dy,k=x+','+y;if(s.floor[y]?.[x]==='.'&&!seen.has(k)){seen.add(k);q.push([x,y]);}}return q;}
function inward(room,d){const [dx,dy]=doorVector(d.wallSide),[x,y]=d.xy;for(const p of [[x-dx,y-dy],[x,y],[x,y+1],[x-1,y],[x+1,y],[x,y-1]])if(room.floor[p[1]]?.[p[0]]==='.')return p;return room.arrive;}
export function ensureStreetServices(data){const town=data.scenes.find(s=>s.key==='town');if(!town)return;const free=reachable(town),used=[...town.objects,...town.doors].map(o=>o.xy).filter(Boolean);for(const [key,label,wish]of [['inn','The Lantern Inn',[7,32]],['clinic','Community infirmary',[40,36]],['carpenter','Joiner’s workshop',[9,40]]]){if([...town.objects,...town.doors].some(o=>o.to===key))continue;const room=data.scenes.find(s=>s.key===key&&s.chapter===1);if(!room)continue;const candidates=free.filter(([x,y])=>DIRS.some(([dx,dy])=>town.floor[y+dy]?.[x+dx]!=='.')&&used.every(p=>Math.hypot(x-p[0],y-p[1])>=3));candidates.sort((a,b)=>Math.hypot(a[0]-wish[0],a[1]-wish[1])-Math.hypot(b[0]-wish[0],b[1]-wish[1]));const xy=candidates[0];if(!xy)throw Error('No clear entrance for '+key);town.objects.push({type:'portal',xy,to:key,travel_label:label,streetService:true,arrive:room.arrive});used.push(xy);}}
export function footprintCells(room){const spans=room.architecture?.outline;if(spans)return spans.flatMap(r=>Array.from({length:r.right-r.left+1},(_,i)=>[r.left+i,r.y]));const floor=room.household?.floorBase||room.floor;return floor.flatMap((r,y)=>[...r].flatMap((v,x)=>v==='.'?[[x,y]]:[]));}
export function exteriorProjection(room,entrance,outside,street){
 const cells=footprintCells(room),door=entrance.xy,side=doorVector(entrance.wallSide),stair=entrance.architecturalKind==='stairs'||/crypt|passages|unindexed/.test(room.key),isYard=room.key==='security';
 let best=null;
 for(let turns=0;turns<4;turns++){const vector=rotateCell(side,turns);if(vector[0]!==0||vector[1]!==1)continue;const rot=cells.map(p=>rotateCell([p[0]-door[0],p[1]-door[1]],turns));const minX=Math.min(...rot.map(p=>p[0])),maxX=Math.max(...rot.map(p=>p[0])),minY=Math.min(...rot.map(p=>p[1])),maxY=Math.max(...rot.map(p=>p[1])),width=maxX-minX+1,depth=maxY-minY+1;
 const baseScale=Math.min(.45,5.5/Math.max(width,depth));for(const scale of [baseScale,baseScale*.92,baseScale*.84]){if(width*scale>6.1||depth*scale>6.1)continue;let clear=0,inRoad=0;for(const [x,y]of rot){const wx=outside[0]+.5+x*scale,wy=outside[1]+.5+y*scale;if(Math.hypot(wx-outside[0]-.5,wy-outside[1]-.5)<.8){clear++;continue;}if(street.floor[Math.floor(wy)]?.[Math.floor(wx)]!=='.')clear++;else inRoad++;}const score=(clear/rot.length)*30-inRoad*.01+scale*45+(street.floor[outside[1]+vector[1]]?.[outside[0]+vector[0]]==='.'?4:0);if(!best||score>best.score)best={turns,scale,vector,cells:rot,bounds:{minX,minY,maxX,maxY},score,clearance:clear/rot.length};}
 }
 if(!best)throw Error('Cannot project building '+room.key);
 return{...best,kind:stair||/hatch|drain|crypt/i.test(street.objects.find(o=>o.xy?.join(',')===outside.join(','))?.travel_label||'')?'underground':isYard?'yard':room.key==='reactor'?'industrial':'building',roomLocation:room.location,style:room.architecture?.style||room.key,material:room.household?.kind||room.interior||'workshop',door:[...door],windowNormal:rotateCell([0,-1],best.turns),windowBays:(room.household?.furnishings||[]).filter(o=>o.furniture===18).map(o=>rotateCell([o.footprint.x+.5-door[0],o.footprint.y+.5-door[1]],best.turns)),outside:[...outside]};
}
export function installBuildingGeometry(data){ensureStreetServices(data);const registry=data.buildingRegistry||[],records=new Map(registry.map(r=>[r.roomLocation,r]));for(const record of registry){record.exteriorLinks=[];record.connections=[];}for(const from of data.scenes)for(const e of [...from.doors,...from.objects.filter(o=>o.type==='portal')]){const target=resolveBuildingTarget(data,from,e),r=records.get(target?.location);if(r)r.connections.push({location:from.location,xy:e.xy,kind:from.household?'interior':'street'});}
 for(const s of data.scenes){s.exteriorBuildings=[];if(s.household)continue;const dedup=new Set();for(const exit of [...s.doors,...s.objects.filter(o=>o.type==='portal')]){const room=resolveBuildingTarget(data,s,exit);if(!room?.household||!exit.xy)continue;const sig=room.location+':'+exit.xy.join(',');if(dedup.has(sig))continue;dedup.add(sig);const back=[...room.doors,...room.objects.filter(o=>o.type==='portal')].find(o=>resolveBuildingTarget(data,room,o)?.location===s.location);if(!back)continue;const entry=inward(room,back),projection=exteriorProjection(room,back,exit.xy,s),id='entrance:'+s.location+':'+room.location+':'+exit.xy.join('-');exit.buildingEntrance={id,roomLocation:room.location,returnLocation:s.location,streetXY:[...exit.xy],roomDoor:[...back.xy],roomSide:back.wallSide};exit.arrive=entry;
 const plan={id,exit,projection};s.exteriorBuildings.push(plan);const record=records.get(room.location);if(record){record.exteriorLinks??=[];record.exteriorLinks=record.exteriorLinks.filter(l=>!(l.location===s.location&&l.xy?.join(',')===exit.xy.join(',')));record.exteriorLinks.push({location:s.location,xy:exit.xy,entranceId:id,turns:projection.turns,scale:projection.scale,kind:projection.kind});}
 }}data.buildingGeometryVersion=1;return data;}
export function rememberBuildingEntry(world,exit){const e=exit.buildingEntrance;if(!e)return;world.state.buildingVisits??={};world.state.buildingVisits[e.roomLocation]={...e};}
export function buildingReturn(world,exit){const e=world.state.buildingVisits?.[world.scene.location];if(!e)return null;const target=resolveBuildingTarget(world.data,world.scene,exit);if(target?.location!==e.returnLocation)return null;return {location:e.returnLocation,xy:e.streetXY};}
